import{_ as o,o as a,c as t,a4 as r}from"./chunks/framework.DpieW3qv.js";const m=JSON.parse('{"title":"Troubleshooting Playbook","description":"","frontmatter":{"title":"Troubleshooting Playbook"},"headers":[],"relativePath":"troubleshooting/playbook.md","filePath":"troubleshooting/playbook.md","lastUpdated":null}'),l={name:"troubleshooting/playbook.md"};function d(i,e,s,n,u,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting-playbook" tabindex="-1">Troubleshooting Playbook <a class="header-anchor" href="#troubleshooting-playbook" aria-label="Permalink to &quot;Troubleshooting Playbook&quot;">​</a></h1><p>Short decision tree for common situations. For full error messages and fixes, see <a href="/ocapi-docs.github.io/troubleshooting/common-errors.html">Common Errors</a> and <a href="/ocapi-docs.github.io/troubleshooting/faq.html">FAQ</a>.</p><hr><h2 id="no-refresh-no-refresh-found" tabindex="-1">No refresh / &quot;No refresh found&quot; <a class="header-anchor" href="#no-refresh-no-refresh-found" aria-label="Permalink to &quot;No refresh / &quot;No refresh found&quot;&quot;">​</a></h2><ol><li>Run <code>make pull</code> to fetch data and create refresh files.</li><li>Run <code>make status</code> to see available dates and refreshes.</li><li>If you need a specific date, ensure the source Excel/Smartsheet has that date and run <code>make pull</code> again.</li></ol><hr><h2 id="already-built" tabindex="-1">&quot;Already built&quot; <a class="header-anchor" href="#already-built" aria-label="Permalink to &quot;&quot;Already built&quot;&quot;">​</a></h2><ul><li><strong>Ready to deploy:</strong> Run <code>make push</code>.</li><li><strong>Need to rebuild</strong> (e.g. after template edits): Run <code>make build FORCE=1</code>, then <code>make push</code>. If that refresh was already synced, use <code>make push FORCE=1</code> to re-sync.</li></ul><hr><h2 id="already-synced-build-or-push-guard" tabindex="-1">&quot;Already synced&quot; (build or push guard) <a class="header-anchor" href="#already-synced-build-or-push-guard" aria-label="Permalink to &quot;&quot;Already synced&quot; (build or push guard)&quot;">​</a></h2><ul><li><strong>Normal next steps:</strong> Run <code>make replicate</code>, then <code>make done</code>, then <code>make commit</code>. Do not re-push unless you have a reason.</li><li><strong>Re-push needed</strong> (e.g. hotfix): Run <code>make build FORCE=1</code>, then <code>make push FORCE=1</code>.</li></ul><hr><h2 id="data-quality-check-failed-on-push" tabindex="-1">Data quality check failed on push <a class="header-anchor" href="#data-quality-check-failed-on-push" aria-label="Permalink to &quot;Data quality check failed on push&quot;">​</a></h2><ol><li>Fix the data in the Excel or Smartsheet source (missing copy, duplicate IPIDs, missing destination, etc.).</li><li>Run <code>make pull</code> to re-fetch.</li><li>Run <code>make build</code> (or <code>make build FORCE=1</code> if already built).</li><li>Run <code>make push</code> again.</li></ol><p>To see quality without pushing, run: <code>node src/cli/index.js validate &lt;brand&gt; [--date=YYYY-MM-DD]</code>.</p><hr><h2 id="ocapi-not-enabled-auth-failures" tabindex="-1">OCAPI not enabled / auth failures <a class="header-anchor" href="#ocapi-not-enabled-auth-failures" aria-label="Permalink to &quot;OCAPI not enabled / auth failures&quot;">​</a></h2><ol><li>Run <code>make setup</code> and enable OCAPI in the wizard.</li><li>Ensure <code>.env</code> has the required SFCC variables (see <a href="/ocapi-docs.github.io/guides/env-and-auth.html">Environment Setup</a>).</li><li>Run <code>make health</code> to verify connectivity.</li></ol><p>If you see 401/403, check <code>SFCC_CLIENT_ID</code>, <code>SFCC_CLIENT_SECRET</code>, and that credentials are valid in Account Manager.</p><hr><h2 id="wrong-date-or-refresh-selected" tabindex="-1">Wrong date or refresh selected <a class="header-anchor" href="#wrong-date-or-refresh-selected" aria-label="Permalink to &quot;Wrong date or refresh selected&quot;">​</a></h2><ul><li><strong>Switch:</strong> Run <code>make select</code> (interactive) or <code>make select DATE=YYYY-MM-DD</code> or <code>make select DATE=YYYY-MM-DD/r2</code>.</li><li><strong>Override for one command:</strong> Pass <code>DATE=</code> or <code>REFRESH=</code> on that command only, e.g. <code>make preview DATE=2026-02-10</code>.</li></ul><hr><h2 id="need-more-detail" tabindex="-1">Need more detail? <a class="header-anchor" href="#need-more-detail" aria-label="Permalink to &quot;Need more detail?&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/troubleshooting/common-errors.html">Common Errors</a> — Full list of messages and resolutions</li><li><a href="/ocapi-docs.github.io/troubleshooting/faq.html">FAQ</a> — Workflow and SFCC questions</li><li><a href="/ocapi-docs.github.io/guides/user-guide.html#5-what-to-do-if">User Guide — What to do if…</a> — Producer-oriented quick answers</li></ul>',25)])])}const f=o(l,[["render",d]]);export{m as __pageData,f as default};
